#!/usr/bin/env node
// Bundle the ranking datasets for the extension: data/*.json -> src/data/*.js
//
//   node scripts/build-data.mjs            # uses data/ccf-2026.json, data/core-2026.json
//   node scripts/build-data.mjs --check    # exit 1 if src/data/*.js is out of date (used by tests/CI)
//
// The extension has no build step, so the generated files are committed. They are
// plain scripts that attach to globalThis.Byline.data (and export under node).
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
let stale = false;

function emit(name, key, payload, source) {
  const body = `// GENERATED by scripts/build-data.mjs from ${source} — do not edit by hand.
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else ((root.Byline = root.Byline || {}).data = (root.Byline && root.Byline.data) || {}).${key} = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";
  return ${JSON.stringify(payload)};
});
`;
  const dest = join(root, "src", "data", name);
  const prev = existsSync(dest) ? readFileSync(dest, "utf8") : "";
  if (check) {
    if (prev !== body) { console.error(`stale: src/data/${name} (run scripts/build-data.mjs)`); stale = true; }
  } else {
    writeFileSync(dest, body);
    console.log(`wrote src/data/${name}  (${payload.venues.length} venues, ${(body.length / 1024).toFixed(0)} KB)`);
  }
}

// ---- CCF
const ccf = JSON.parse(readFileSync(join(root, "data", "ccf-2026.json"), "utf8"));
emit("ccf.js", "ccf", {
  meta: { label: "CCF 2026 (7th edition)", edition: ccf.meta.edition, counts: ccf.meta.counts },
  venues: ccf.venues.map((v) => ({ kind: v.kind, tier: v.tier, abbr: v.abbr, name: v.name, area: v.area, dblp: v.dblp }))
}, "data/ccf-2026.json");

// ---- CORE
const core = JSON.parse(readFileSync(join(root, "data", "core-2026.json"), "utf8"));
emit("core.js", "core", {
  meta: { label: "ICORE 2026", edition: core.meta.edition, counts: core.meta.counts },
  venues: core.venues.map((v) => ({ acronym: v.acronym, name: v.name, rank: v.rank }))
}, "data/core-2026.json");

if (check && stale) process.exit(1);
